const types=['Chaotic','Euclidean','Quadrature','Custom','Sub oscillator'],colors=['#d990c6','#8dc9c8','#d5b77a','#b3bf92','#e5e8dc'],icons=['〰','◉','∿','⌁','≋'];
const definitions=[['Rate','Sigma','Rho','Beta'],['Rate','Steps','Beats','Shift'],['Rate','Phase spread','Ratio','Drift'],['Rate','Steps','Skew','Smooth'],['Frequency','Harmonics','Sub weight','Saturation']];
