let state={mode:'Simple',selected:0,preset:0,macros:[...patchDefs[0][4]],gens:types.map((type,i)=>({type,name:['Lorenz attractor','Euclidean rhythm','Quadrature LFO','Custom waveform','Sub oscillator'][i],params:[...defaults[i]],muted:false,algorithm:'Lorenz'})),routes:[{from:0,to:1,depth:30,lag:10,bipolar:true},{from:2,to:0,depth:24,lag:5,bipolar:true},{from:1,to:3,depth:40,lag:0,bipolar:false},{from:3,to:4,depth:38,lag:20,bipolar:true},{from:0,to:2,depth:20,lag:10,bipolar:true},{from:4,to:0,depth:15,lag:15,bipolar:false}]};
try{const saved=JSON.parse(localStorage.getItem('blackbox-patch'));if(saved?.gens?.length&&saved.macros?.length===6)state=saved}catch{}
let running=false,frozen=false,view='Orbit',audio,processor,gain,phase=0,audioTime=0,last=0;
const toast=t=>{$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.opacity=0,2500)};
function persist(){localStorage.setItem('blackbox-patch',JSON.stringify(state))}
function render(){document.body.classList.toggle('automated',state.mode==='Automated');$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-selected',b.dataset.mode===state.mode)});$('#modeHint').textContent={Automated:'',Simple:'',Advanced:''}[state.mode];$('#advanced').hidden=state.mode!=='Advanced';$('#generators').innerHTML=state.gens.map((g,i)=>`<button class="gen ${i===state.selected?'active':''}" data-gen="${i}" title="${g.name} — ${g.type}${g.muted?' (muted)':''}" aria-label="${g.name} — ${g.type}${g.muted?' (muted)':''}" aria-pressed="${i===state.selected}" style="color:${colors[types.indexOf(g.type)]}"><span class="icon">${icons[types.indexOf(g.type)]}</span><span><b>${g.name}</b><small>${g.type==='Chaotic'?'3 OUTPUTS':g.type==='Quadrature'?'4 OUTPUTS':'2 OUTPUTS'} · ${g.muted?'MUTED':'SYNC'}</small></span><span class="genled" role="switch" aria-label="Mute ${g.type}" aria-checked="${!g.muted}" data-mute="${i}">${g.muted?'○':'●'}</span></button>`).join('');
$$('[data-gen]').forEach(b=>b.onclick=e=>{if(e.target.dataset.mute!==undefined){state.gens[+e.target.dataset.mute].muted=!state.gens[+e.target.dataset.mute].muted}else state.selected=+b.dataset.gen;render();persist()});
const g=state.gens[state.selected],ti=types.indexOf(g.type);$('#vizName').textContent=g.name;$('#vizType').textContent=g.type.toUpperCase()+' GENERATOR';$('.dot').style.background=colors[ti];$('#paramName').textContent=g.type==='Chaotic'?g.algorithm:g.type.split(' ')[0];$('#algorithm').hidden=g.type!=='Chaotic';$('#algorithm').value=g.algorithm;$('#parameters').innerHTML=g.params.map((v,i)=>`<div class="param"><label for="param${i}">${definitions[ti][i]}<output id="pv${i}">${formatParam(ti,i,v)}</output></label><input id="param${i}" type="range" min="0" max="100" value="${v}" data-param="${i}"></div>`).join('');$$('[data-param]').forEach(r=>r.oninput=()=>{g.params[+r.dataset.param]=+r.value;$('#pv'+r.dataset.param).textContent=formatParam(ti,+r.dataset.param,+r.value);persist()});
$('#macros').innerHTML=['Chaos','Density','Drift','Harmonics','Sub weight','Intensity'].map((name,i)=>`<div class="macro"><div class="knob" style="--v:${state.macros[i]}"><input type="range" min="0" max="100" value="${state.macros[i]}" aria-label="${name}" data-macro="${i}"></div><b>${name}</b><output>${state.macros[i]}%</output></div>`).join('');$$('[data-macro]').forEach(r=>r.oninput=()=>{state.macros[+r.dataset.macro]=+r.value;r.parentElement.style.setProperty('--v',r.value);r.parentElement.parentElement.querySelector('output').textContent=r.value+'%';persist()});
$('#presets').innerHTML=patchDefs.map((p,i)=>`<button class="preset ${state.preset===i?'active':''}" data-preset="${i}"><span class="art" style="color:${colors[i]}">${p[3]}</span><span><b>${p[0]}</b><small>${p[2]}</small></span><span class="number">0${i+1}</span></button>`).join('');$$('[data-preset]').forEach(b=>b.onclick=()=>loadPreset(+b.dataset.preset));$('#patchName').replaceChildren(document.createTextNode(patchDefs[state.preset][0]),Object.assign(document.createElement('span'),{textContent:' / 0'+(state.preset+1)}));$('#patchDesc').textContent=patchDefs[state.preset][1];$('#genCount').textContent=String(state.gens.length).padStart(2,'0');$('#footerMode').textContent=`${state.mode.toUpperCase()} MODE  •  ${state.gens.length} GENERATORS  •  ${state.routes.length} ROUTES`;renderRoutes();}
function formatParam(t,i,v){if(i===0)return t===4?Math.round(25+v*2)+' Hz':(v/50).toFixed(2)+' Hz';if(t===1||t===3&&i===1)return Math.round(v*.31+1);if(t===2&&i===1)return Math.round(v*3.6)+'°';return (v*.6).toFixed(1)}
function renderRoutes(){const opts=sel=>state.gens.map((g,i)=>`<option value="${i}" ${i===sel?'selected':''}>${i+1}. ${g.type}</option>`).join('');$('#routes').innerHTML=state.routes.map((r,i)=>`<div class="route"><select aria-label="Route ${i+1} source" data-route="${i}" data-key="from">${opts(r.from)}</select><span>→</span><select aria-label="Route ${i+1} destination rate" data-route="${i}" data-key="to">${opts(r.to)}</select><label>Rate depth <output>${r.depth}%</output><input aria-label="Route ${i+1} depth" type="range" min="-100" max="100" value="${r.depth}" data-route="${i}" data-key="depth"></label><label>Lag <input aria-label="Route ${i+1} lag" type="range" min="0" max="100" value="${r.lag}" data-route="${i}" data-key="lag"></label><label><input type="checkbox" ${r.bipolar?'checked':''} data-route="${i}" data-key="bipolar"> Bipolar</label><button aria-label="Remove route ${i+1}" data-remove="${i}">×</button></div>`).join('');$$('[data-route]').forEach(el=>el.oninput=()=>{state.routes[+el.dataset.route][el.dataset.key]=el.type==='checkbox'?el.checked:+el.value;if(el.dataset.key==='depth')el.previousElementSibling.textContent=el.value+'%';persist()});$$('[data-remove]').forEach(b=>b.onclick=()=>{state.routes.splice(+b.dataset.remove,1);render();persist()})}
function loadPreset(i){state.preset=(i+4)%4;state.macros=[...patchDefs[state.preset][4]];state.gens.forEach((g,j)=>g.params=defaults[types.indexOf(g.type)].map((v,k)=>Math.min(100,Math.max(0,v+(state.preset?Math.sin(j+k+state.preset)*20:0)))));render();persist();toast('Loaded '+patchDefs[state.preset][0])}
$$('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;render();persist()});$$('[data-viz]').forEach(b=>b.onclick=()=>{view=b.dataset.viz;$$('[data-viz]').forEach(x=>x.classList.toggle('selected',x===b))});$('#freeze').onclick=()=>{frozen=!frozen;$('#freeze').textContent=frozen?'▶':'Ⅱ'};$('#prev').onclick=()=>loadPreset(state.preset-1);$('#next').onclick=()=>loadPreset(state.preset+1);$('#random').onclick=()=>{state.macros=state.macros.map(()=>Math.round(Math.random()*100));render();persist();toast('Patch mutated')};$('#reset').onclick=()=>{state.gens[state.selected].params=[...defaults[types.indexOf(state.gens[state.selected].type)]];render();persist()};$('#algorithm').onchange=e=>{state.gens[state.selected].algorithm=e.target.value;state.gens[state.selected].name=e.target.value+' attractor';render();persist()};$('#add').onclick=()=>{if(state.gens.length>=8)return toast('Eight generators is the current limit.');const ti=state.gens.length%5;state.gens.push({type:types[ti],name:types[ti]+' '+(state.gens.length+1),params:[...defaults[ti]],muted:false,algorithm:'Lorenz'});state.selected=state.gens.length-1;render();persist()};$('#addRoute').onclick=()=>{state.routes.push({from:state.selected,to:(state.selected+1)%state.gens.length,depth:20,lag:0,bipolar:true});render();persist()};$('#sync').onclick=()=>{$('#sync').classList.toggle('selected');$('#sync').textContent=$('#sync').classList.contains('selected')?'SYNC':'FREE'};$('#help').onclick=()=>$('#helpDialog').showModal();$('#closeHelp').onclick=()=>$('#helpDialog').close();$('#save').onclick=()=>{const blob=new Blob([JSON.stringify({...state,bpm:+$('#bpm').value},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='motherbox-patch.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Patch saved')};
let phases=new Float64Array(8),outputs=new Float64Array(8),smoothed=new Float64Array(32),cx=0.1,cy=0,cz=0;
let tempo=1; function tick(dt){const m=state.macros;for(let i=0;i<state.gens.length;i++){let g=state.gens[i],p=g.params,t=types.indexOf(g.type),mod=0;state.routes.forEach((r,j)=>{if(r.to===i){let target=outputs[r.from]||0;if(!r.bipolar)target=(target+1)/2;smoothed[j]+=(target-smoothed[j])*Math.min(1,dt/(.001+r.lag*.003));mod+=smoothed[j]*r.depth*.015*(m[5]/70+.2)}});let freq=t===4?25+p[0]*2:Math.max(.01,(p[0]/50)*tempo*(1+mod));phases[i]+=dt*freq;const a=phases[i]*Math.PI*2;let value=0;if(t===0){let step=dt*freq*9;cx+=10*(cy-cx)*step;cy+=(cx*((15+p[2]*.55+m[0]*.15)-cz)-cy)*step;cz+=(cx*cy-(1+p[3]*.06)*cz)*step;if(!Number.isFinite(cx)||Math.abs(cx)>1000){cx=.1;cy=0;cz=0}value=Math.tanh(cx/16);if(g.algorithm==='Logistic')value=Math.sin(a*1.7+Math.sin(a*2.9)*m[0]/10);if(g.algorithm==='Rössler')value=Math.sin(a+Math.sin(a*.37)*m[0]/20);if(g.algorithm==='Hénon')value=Math.tanh(Math.sin(a*1.6)*3+Math.sin(a*2.7))}else if(t===1){const steps=Math.max(1,Math.round(p[1]*.31+1)),beats=Math.min(steps,Math.round((p[2]/100+m[1]/200)*steps));let s=Math.floor(phases[i]*steps/4+p[3]/10)%steps;value=(s*beats)%steps<beats?1:-1}else if(t===2)value=Math.sin(a+p[1]/100*Math.PI*2+Math.sin(a*.13)*m[2]/90);else if(t===3)value=Math.tanh(Math.sin(a)+Math.sin(a*3)*(1-p[3]/110));else value=Math.sin(a)+(p[1]+m[3])*.004*Math.sin(a*2)+m[4]*.006*Math.sin(a/2);outputs[i]=g.muted?0:value}return outputs}
$('#play').onclick=async()=>{try{if(!audio){audio=new AudioContext();processor=audio.createScriptProcessor(1024,0,2);gain=audio.createGain();gain.gain.value=.09;processor.onaudioprocess=e=>{tempo=document.getElementById('sync').classList.contains('selected')?(+document.getElementById('bpm').value||120)/120:1;const clip=document.getElementById('softclip').checked;const l=e.outputBuffer.getChannelData(0),r=e.outputBuffer.getChannelData(1);for(let s=0;s<l.length;s++){const out=tick(1/audio.sampleRate);let v=0;state.gens.forEach((g,i)=>{if(g.type==='Sub oscillator')v+=out[i]*.5});v+=Math.sin(2*Math.PI*55*audioTime+out[0]*state.macros[0]/35)*(.1+state.macros[5]/600);audioTime+=1/audio.sampleRate;v*=(.3+state.macros[5]/90);if(clip)v=Math.tanh(v*1.6);l[s]=r[s]=v} };processor.connect(gain);gain.connect(audio.destination)}running=!running;if(running)await audio.resume();else await audio.suspend();$('#play').textContent=running?'Ⅱ':'▶';$('#play').setAttribute('aria-label',running?'Stop audio':'Start audio');$('#audioStatus').textContent=running?'LIVE':'STANDBY';updateVolume()}catch(e){toast('Audio unavailable in this browser. Visual mode remains active.')}};
function updateVolume(){if(gain)gain.gain.setTargetAtTime($('#volume').value/100*.2,audio.currentTime,.03);$('#db').textContent=Math.round(20*Math.log10(Math.max(.001,$('#volume').value/100*.45)))+' dB'}$('#volume').oninput=updateVolume;
const canvas=$('#scope'),ctx=canvas.getContext('2d');let points=[];function draw(now){requestAnimationFrame(draw);if(frozen)return;const dt=Math.min(.04,(now-last)/1000||.016);last=now;phase+=dt;if(!running)for(let n=0;n<8;n++)tick(dt/8);const dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==w*dpr||canvas.height!==h*dpr){canvas.width=w*dpr;canvas.height=h*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#65735815';ctx.lineWidth=1;for(let x=0;x<w;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle='#75876626';ctx.setLineDash([3,5]);ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.stroke();ctx.setLineDash([]);let ti=types.indexOf(state.gens[state.selected].type),c=colors[ti],m=state.macros;
if(view==='Waveform'||ti===2||ti===3||ti===4){for(let j=0;j<(ti===2?4:3);j++){ctx.beginPath();ctx.strokeStyle=[c,colors[(ti+1)%5],colors[(ti+2)%5]][j%3];ctx.globalAlpha=j===0?1:.45;for(let x=0;x<w;x++){let t=x/w*Math.PI*(4+m[1]/20)+phase*(.5+state.gens[state.selected].params[0]/40),y=Math.sin(t+j*Math.PI/2+Math.sin(t*2)*m[0]/100)*(h*.22)+Math.sin(t*3)*m[3]/100*h*.06;ti===3&&(y=Math.tanh(y/h*5)*h*.29);x?ctx.lineTo(x,h/2+y):ctx.moveTo(x,h/2+y)}ctx.lineWidth=1.4;ctx.shadowBlur=5;ctx.shadowColor=ctx.strokeStyle;ctx.stroke();ctx.shadowBlur=0}ctx.globalAlpha=1}else if(ti===1){let steps=Math.round(state.gens[state.selected].params[1]*.31+1),beats=Math.round(steps*(state.gens[state.selected].params[2]/120+m[1]/250));for(let j=0;j<3;j++){let radius=50+j*31;ctx.strokeStyle='#48553b';ctx.beginPath();ctx.arc(w/2,h/2,radius,0,Math.PI*2);ctx.stroke();for(let s=0;s<steps;s++){let a=s/steps*Math.PI*2-Math.PI/2,on=s*beats%steps<beats;ctx.fillStyle=on?c:'#394233';ctx.beginPath();ctx.arc(w/2+Math.cos(a)*radius,h/2+Math.sin(a)*radius,on?4:2,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#effadc';let a=phase*.7+j;ctx.beginPath();ctx.arc(w/2+Math.cos(a)*radius,h/2+Math.sin(a)*radius,5,0,Math.PI*2);ctx.fill()}}else{const rot=Math.sin(phase*.13)*.13,scale=Math.min(w/95,h/65)*1.05;for(let layer=0;layer<3;layer++){let x=.1,y=0,z=0;ctx.beginPath();for(let n=0;n<3900;n++){const dt=.006;x+=10*(y-x)*dt;y+=(x*(28+(m[0]-50)*.12-z)-y)*dt;z+=(x*y-2.667*z)*dt;const px=w/2+(x*Math.cos(rot)+(z-25)*Math.sin(rot))*scale*1.25,py=h*.52+(z-25)*scale*.89+Math.sin(phase*.3+layer)*2;if(n>80){n===81?ctx.moveTo(px,py):ctx.lineTo(px,py)}}ctx.strokeStyle=layer===0?'#d5eda3':layer===1?'#adc87c55':'#d990c633';ctx.lineWidth=layer===0?.65:1;ctx.shadowBlur=layer===0?4:0;ctx.shadowColor='#c6e995';ctx.stroke();ctx.shadowBlur=0}for(let i=0;i<15;i++){const t=phase*.23+i*.41,x=w/2+Math.sin(t)*Math.cos(t*.47)*w*.27,y=h/2+Math.sin(t*2)*h*.29;ctx.fillStyle='#d9efac';ctx.globalAlpha=.4;ctx.fillRect(x,y,1.5,1.5)}ctx.globalAlpha=1}
$('#sx').textContent=(outputs[0]||0).toFixed(3);$('#sy').textContent=(outputs[2]||0).toFixed(3);$('#sz').textContent=(outputs[3]||0).toFixed(3);$('#signalRate').textContent=formatParam(ti,0,state.gens[state.selected].params[0]);$$('.meters div').forEach((el,i)=>el.style.width=running?(40+Math.abs(Math.sin(phase*9+i))*(state.macros[5]/2))+'%':'7%')}
